      const TeamValidator2 = (init_team_validator(), __toCommonJS(team_validator_exports)).TeamValidator;
      const natDex = TeamValidator2.get(`gen${this.gen}nationaldexag`).checkCanLearn(move, species, this.allSources(species), set);
